#!/usr/bin/env python3
"""Generate translation/src/dtoa_tables.rs from c_src/src/dtoa.c."""
import re, sys

SRC = "$HARVEST_WORKDIR/c_src/src/dtoa.c"
OUT = "$HARVEST_WORKDIR/translation/src/dtoa_tables.rs"

text = open(SRC).read()

def grab(decl):
    """Return the initialiser text of `decl` (up to the matching '};')."""
    i = text.index(decl)
    j = text.index("{", i + len(decl) - 1)
    # find the terminating "};" at brace depth 0
    depth = 0
    k = j
    while True:
        if text[k] == '{':
            depth += 1
        elif text[k] == '}':
            depth -= 1
            if depth == 0:
                break
        k += 1
    return text[j + 1:k]

def strip_comments(s):
    s = re.sub(r"/\*.*?\*/", "", s, flags=re.S)
    s = re.sub(r"//[^\n]*", "", s)
    return s

# ---- pten: 667 { b0, b1, b2, e } entries -------------------------------
pten_body = strip_comments(grab("static BF96 pten[667] ="))
entries = re.findall(r"\{([^{}]*)\}", pten_body)
assert len(entries) == 667, len(entries)
pten_rows = []
for e in entries:
    parts = [p.strip() for p in e.split(",")]
    assert len(parts) == 4, parts
    b0, b1, b2, ex = parts
    pten_rows.append("    BF96 { b0: %s, b1: %s, b2: %s, e: %s }," % (b0, b1, b2, ex))

# ---- Lhint: 2098 shorts ------------------------------------------------
lh_body = strip_comments(grab("static short int Lhint[2098] ="))
lh = [x.strip() for x in lh_body.replace("\n", " ").split(",")]
lh = [x for x in lh if x != ""]
assert len(lh) == 2098, len(lh)

# ---- pfive: 27 u64 -----------------------------------------------------
pf_body = strip_comments(grab("static ULLong pfive[27] ="))
pf = [x.strip().replace("ll", "") for x in pf_body.replace("\n", " ").split(",")]
pf = [x for x in pf if x != ""]
assert len(pf) == 27, len(pf)

# ---- pfivebits: 25 ints ------------------------------------------------
pb_body = strip_comments(grab("static int pfivebits[25] ="))
pb = [x.strip() for x in pb_body.replace("\n", " ").split(",")]
pb = [x for x in pb if x != ""]
assert len(pb) == 25, len(pb)

# ---- hexdig: 256 bytes (the pre-initialised variant) -------------------
hd_body = strip_comments(grab("static unsigned char hexdig[256] ="))
hd = [x.strip() for x in hd_body.replace("\n", " ").split(",")]
hd = [x for x in hd if x != ""]
assert len(hd) == 256, len(hd)

def rows(items, per_line, indent="    "):
    out = []
    for i in range(0, len(items), per_line):
        out.append(indent + ", ".join(items[i:i + per_line]) + ",")
    return "\n".join(out)

with open(OUT, "w") as f:
    f.write("""//! Constant tables extracted verbatim from `src/dtoa.c`.
//!
//! Generated by `tools/gen_dtoa_tables.py`; do not edit by hand.

/// Normalized 96-bit software floating point numbers:
/// the value represented is `b * 2^e` with `.5 <= b < 1`.
#[derive(Clone, Copy)]
pub struct BF96 {
    pub b0: u32,
    pub b1: u32,
    pub b2: u32,
    pub e: i32,
}

pub static pten: [BF96; 667] = [
""")
    f.write("\n".join(pten_rows))
    f.write("\n];\n\n")

    f.write("pub static Lhint: [i16; 2098] = [\n")
    f.write(rows(lh, 12))
    f.write("\n];\n\n")

    f.write("pub static pfive: [u64; 27] = [\n")
    f.write(rows(pf, 4))
    f.write("\n];\n\n")

    f.write("pub static pfivebits: [i32; 25] = [\n")
    f.write(rows(pb, 13))
    f.write("\n];\n\n")

    f.write("pub static hexdig: [u8; 256] = [\n")
    f.write(rows(hd, 16))
    f.write("\n];\n\n")

    f.write("""pub static tens: [f64; 23] = [
    1e0, 1e1, 1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8, 1e9, 1e10, 1e11, 1e12, 1e13, 1e14, 1e15,
    1e16, 1e17, 1e18, 1e19, 1e20, 1e21, 1e22,
];

pub static bigtens: [f64; 5] = [1e16, 1e32, 1e64, 1e128, 1e256];
pub const n_bigtens: i32 = 5;

pub static tinytens: [f64; 5] = [
    1e-16,
    1e-32,
    1e-64,
    1e-128,
    9007199254740992.0 * 9007199254740992.0e-256,
];
""")

print("wrote", OUT)
